import java.nio.file.*;import org.json.*;
public final class AbyssResolveAudit {
 public static void main(String[] args)throws Exception{JSONArray fixtures=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),"UTF-8")).getJSONArray("fixtures"),results=new JSONArray();int passed=0;for(int i=0;i<fixtures.length();i++){JSONObject f=fixtures.getJSONObject(i),result=new JSONObject().put("title",f.getString("title"));long start=System.nanoTime();NativeHttp.CURRENT.set(new NativeHttp.Session(25000));try{NativeCatalog.Candidate selected=null;for(NativeCatalog.Candidate c:new FdCatalog().discover(f.getJSONObject("data")))if(c.host.equals("Abyss")){selected=c;break;}if(selected==null)throw new Exception("No Abyss candidate");ResolvedStream stream=RoDubbedProvider.resolve(selected);result.put("pass",true).put("quality",stream.quality);passed++;}catch(Exception e){result.put("pass",false).put("error",e.getMessage());}finally{NativeHttp.session().stop();NativeHttp.CURRENT.remove();}result.put("ms",(System.nanoTime()-start)/1000000);results.put(result);System.out.println(result.toString());}Files.write(Paths.get(args[1]),new JSONObject().put("passed",passed).put("total",fixtures.length()).put("results",results).toString(2).getBytes("UTF-8"));}
}
